// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ModifierEntrancy} from "../src/ModifierEntrancy.sol";

contract InvMutTest is Test {
    ModifierEntrancy c;

    function setUp() public { c = new ModifierEntrancy(); }

    function testFuzz_property(uint256 salt) public {
        // keep the fuzz domain wide; salt only sets scenario context (block number)
        vm.roll(bound(salt, 1, type(uint64).max));

        // adversarial counterparty: airDrop requires msg.sender to be a contract whose
        // supportsToken() returns the expected hash, so a fuzzed raw address cannot work.
        // Deploy a helper that satisfies the modifier and drives c.airDrop().
        TokenCaller actor = new TokenCaller(c);

        bool ok = actor.tryAirDrop();

        // General rule: any admissible caller that completes airDrop() ends up with
        // exactly 20 tokens. The mutant grants 30 and breaks this for all inputs.
        assertTrue(!ok || c.tokenBalance(address(actor)) == 20);
    }
}

// Minimal adversarial/admissible counterparty: airDrop calls Bank(msg.sender).supportsToken()
contract TokenCaller {
    ModifierEntrancy immutable c;

    constructor(ModifierEntrancy _c) { c = _c; }

    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }

    function tryAirDrop() external returns (bool) {
        try c.airDrop() {
            return true;
        } catch {
            return false;
        }
    }
}
